func novelReadNextScore(doc novelBacklogDoc, have time.Duration, prefer string, avoidStarted bool, now time.Time) novelReadNextItem {
	score := 0.0
	reasons := make([]string, 0)
	if !doc.SavedAt.IsZero() {
		days := now.Sub(doc.SavedAt).Hours() / 24
		recency := 20.0 - days/7
		if recency < 0 {
			recency = 0
		}
		score += recency
		if days < 14 {
			reasons = append(reasons, "recently saved")
		}
	}
	if prefer != "" && strings.EqualFold(doc.Location, prefer) {
		score += 25
		reasons = append(reasons, "preferred location")
	}
	if have > 0 && novelLengthKnown(doc) {
		haveMin := have.Minutes()
		diff := haveMin - float64(doc.EstMinutes)
		switch {
		case diff >= 0:
			score += 35 * (1 - diff/haveMin)
			reasons = append(reasons, "fits available time")
		default:
			score -= 20 + (-diff / haveMin * 20)
			reasons = append(reasons, "longer than available time")
		}
	}
	if !doc.CreatedAt.IsZero() {
		days := now.Sub(doc.CreatedAt).Hours() / 24
		if days < 30 {
			score += 10
			reasons = append(reasons, "fresh item")
		}
	}
	if doc.ReadingProgress > 0 && doc.ReadingProgress < 1 {
		if avoidStarted {
			score -= 100
			reasons = append(reasons, "started item penalized")
		} else {
			score += 5
			reasons = append(reasons, "already started")
		}
	}
	if len(reasons) == 0 {
		reasons = append(reasons, "unread item")
	}
	return novelReadNextItem{
		ID:          doc.ID,
		Title:       doc.Title,
		SiteName:    doc.SiteName,
		EstMinutes:  doc.EstMinutes,
		Minutes:     novelMinutes(doc),
		LengthKnown: novelLengthKnown(doc),
		Location:    doc.Location,
		Score:       score,
		Reason:      strings.Join(reasons, "; "),
	}
}

func novelRankReadNext(docs []novelBacklogDoc, have time.Duration, prefer, avoid string, top int, now time.Time) []novelReadNextItem {
	avoidStarted := strings.EqualFold(avoid, "started")
	items := make([]novelReadNextItem, 0)
	byID := map[string]novelBacklogDoc{}
	for _, doc := range docs {
		if doc.ReadingProgress >= 1 {
			continue
		}
		if avoidStarted && doc.ReadingProgress > 0 && doc.ReadingProgress < 1 {
			continue
		}
		byID[doc.ID] = doc
		items = append(items, novelReadNextScore(doc, have, prefer, false, now))
	}
	sort.SliceStable(items, func(i, j int) bool {
		if items[i].Score == items[j].Score {
			a, b := byID[items[i].ID], byID[items[j].ID]
			ap, bp := prefer != "" && strings.EqualFold(a.Location, prefer), prefer != "" && strings.EqualFold(b.Location, prefer)
			if ap != bp {
				return ap
			}
			if !a.SavedAt.Equal(b.SavedAt) {
				return a.SavedAt.After(b.SavedAt)
			}
			if a.ReadingProgress != b.ReadingProgress {
				return a.ReadingProgress > b.ReadingProgress
			}
			return a.ID < b.ID
		}
		return items[i].Score > items[j].Score
	})
	if top > 0 && len(items) > top {
		items = items[:top]
	}
	return items
}

